<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\SnippetVersionSnippetVO;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;

final class SnippetVersionSnippetVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new SnippetRef('one');
        $ref = SnippetVersionSnippetVO::from($value);
        $this->assertEquals(new SnippetRef('one'), $ref->value());
        $other = SnippetVersionSnippetVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = SnippetVersionSnippetVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = SnippetVersionSnippetVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(SnippetVersionSnippetVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = SnippetVersionSnippetVO::from(new SnippetRef('one'));
        $same = SnippetVersionSnippetVO::from(new SnippetRef('one'));
        $other = SnippetVersionSnippetVO::from(new SnippetRef('other'));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
}
